import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.IOException;
import java.util.logging.Logger;

public class AccountLookupServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(AccountLookupServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String accountId = req.getParameter("id");
        String fields = req.getParameter("fields");

        if (accountId == null || accountId.isEmpty()) {
            resp.sendError(400, "Missing id parameter");
            return;
        }

        // Basic input length check
        if (accountId.length() > 64 || (fields != null && fields.length() > 256)) {
            resp.sendError(400, "Input too long");
            return;
        }

        // Whitelist check on accountId - only alphanumeric and hyphens
        if (!accountId.matches("^[a-zA-Z0-9\\-]+$")) {
            resp.sendError(400, "Invalid account ID format");
            return;
        }

        // Fields parameter allows selecting which columns to return
        // Default to safe subset if not specified
        String columnList = "account_id, display_name, created_at";
        if (fields != null && !fields.isEmpty()) {
            // Allow caller to specify columns - we trust the regex on accountId
            // but fields is used directly in column selection
            columnList = fields;
        }

        String query = "SELECT " + columnList + " FROM accounts WHERE account_id = '" + accountId + "'";
        log.info("Executing query for account: " + accountId);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement()) {

            // Set query timeout to prevent long-running queries
            stmt.setQueryTimeout(5);

            ResultSet rs = stmt.executeQuery(query);
            resp.setContentType("application/json");
            StringBuilder json = new StringBuilder("{\"results\":[");
            ResultSetMetaData meta = rs.getMetaData();
            boolean first = true;

            while (rs.next()) {
                if (!first) json.append(",");
                json.append("{");
                for (int i = 1; i <= meta.getColumnCount(); i++) {
                    if (i > 1) json.append(",");
                    json.append("\"").append(meta.getColumnLabel(i)).append("\":");
                    json.append("\"").append(rs.getString(i)).append("\"");
                }
                json.append("}");
                first = false;
            }
            json.append("]}");
            resp.getWriter().write(json.toString());

        } catch (SQLException e) {
            log.warning("Database error: " + e.getMessage());
            resp.sendError(500, "Internal error");
        }
    }
}
